// Helper functions
function searchDrugs(query, category = null, company = null) {
    let results = EGYPTIAN_DRUGS;
    
    if (query) {
        const q = query.toLowerCase();
        results = results.filter(drug => 
            drug.tradeName.toLowerCase().includes(q) ||
            drug.scientificName.toLowerCase().includes(q) ||
            drug.company.toLowerCase().includes(q)
        );
    }
    
    if (category) {
        results = results.filter(drug => drug.category === category);
    }
    
    if (company) {
        results = results.filter(drug => drug.company === company);
    }
    
    return results;
}

function getDrugCategories() {
    return [...new Set(EGYPTIAN_DRUGS.map(drug => drug.category))];
}

function getDrugCompanies() {
    return [...new Set(EGYPTIAN_DRUGS.map(drug => drug.company))];
}

function getDrugById(id) {
    return EGYPTIAN_DRUGS.find(drug => drug.id === id);
}

function getDrugsByCategory(category) {
    return EGYPTIAN_DRUGS.filter(drug => drug.category === category);
}

function getDrugsByCompany(company) {
    return EGYPTIAN_DRUGS.filter(drug => drug.company === company);
}

// Export for use in other modules
window.EGYPTIAN_DRUGS = EGYPTIAN_DRUGS;
window.searchDrugs = searchDrugs;
window.getDrugCategories = getDrugCategories;
window.getDrugCompanies = getDrugCompanies;
window.getDrugById = getDrugById;
window.getDrugsByCategory = getDrugsByCategory;
window.getDrugsByCompany = getDrugsByCompany;
